function once(fn) {
  var called = false;
  var value;
  return function () {
    if (called) return value;
    called = true;
    value = fn.apply(this, arguments);
    return value;
  };
}

function sum(n) {
  if (n === undefined) return 0;
  var total = n;
  function next(m) {
    if (m === undefined) return total;
    total += m;
    return next;
  }
  return next;
}

