function memoize(fn) {
  var cache = new Map();
  return function () {
    var key = JSON.stringify([].slice.call(arguments));
    if (cache.has(key)) return cache.get(key);
    var value = fn.apply(this, arguments);
    cache.set(key, value);
    return value;
  };
}

